            if(!source.XAxis.EpsilonEquals(target.XAxis,ConfiguredPoseDimensionTolerance)||!source.YAxis.EpsilonEquals(target.YAxis,ConfiguredPoseDimensionTolerance))return null;
            templates.Add(existing with {Table=table});
