      }
      private void RetainPreviewCopies(IEnumerable<Row> rows)
      {
        var retained=rows.SelectMany(row=>row.InstanceIds()).ToHashSet();
        foreach(var key in _partFills.Keys.Where(key=>!retained.Contains(key.Id)).ToArray())
        {_partFills[key].Mesh.Dispose();_partFills.Remove(key);}
        foreach(int id in _sourcePartFills.Keys.Where(id=>!retained.Contains(id)).ToArray())
        {foreach(var fill in _sourcePartFills[id].Fills)fill.Mesh.Dispose();_sourcePartFills.Remove(id);}
        foreach(int id in _manualInstances.Keys.Where(id=>!retained.Contains(id)).ToArray())_manualInstances.Remove(id);
        if(_activePreviewInstance is {} active&&!retained.Contains(active))_activePreviewInstance=null;
        foreach(var id in _previewCopies.Keys.Where(id=>!retained.Contains(id)).ToArray())
        {foreach(var item in _previewCopies[id].Items)item.Geometry.Dispose();_previewCopies.Remove(id);}
        foreach(var id in _previewOutlines.Keys.Where(id=>!retained.Contains(id)).ToArray())
        {_previewOutlines[id].Outline.Dispose();_previewOutlines.Remove(id);_previewClearance.Remove(id);}
      }

      private Curve PreviewOutline(Row row,NestPackingEngine.Placement placement)
      {
        var transform=InstanceTransform(row,placement);
        if(_previewOutlines.TryGetValue(placement.Id,out var cached))
        {
          if(cached.Transform==transform)return cached.Outline;
          if(cached.Transform.TryGetInverse(out var inverse)&&cached.Outline.Transform(transform*inverse))
          {_previewOutlines[placement.Id]=(transform,cached.Outline);return cached.Outline;}
          cached.Outline.Dispose();
        }
        var outline=row.Part.Outline.DuplicateCurve();outline.Transform(transform);
        _previewOutlines[placement.Id]=(transform,outline);return outline;
      }
      private IReadOnlyList<Polyline> PreviewClearance(Row row,NestPackingEngine.Placement placement)
      {
        double gap=TableMaterial(placement.Table).Gap;if(gap<=0)return [];
        var transform=InstanceTransform(row,placement);
        if(_previewClearance.TryGetValue(placement.Id,out var cached)&&cached.Gap==gap)
        {
          if(cached.Transform==transform)return cached.Contours;
          if(cached.Transform.TryGetInverse(out var inverse))
          {foreach(var path in cached.Contours)path.Transform(transform*inverse);_previewClearance[placement.Id]=(transform,gap,cached.Contours);return cached.Contours;}
        }
        var contours=row.Clearance(gap).Select(path=>{var copy=new Polyline(path);copy.Transform(transform);return copy;}).ToArray();
        _previewClearance[placement.Id]=(transform,gap,contours);return contours;
      }
      private IEnumerable<(Row Row,NestPackingEngine.Placement Placement)> GapPreviewParts()
      {
        if(_locationPicking||_shownGapState==false)yield break;
        if(_shownGapState==null)
        {foreach(var part in _activePreviewParts)yield return part;yield break;}
        foreach(var placement in VisibleResult.Placements)
          if(PlacementOwner(placement.Id) is {} row)yield return (row,placement);
      }

      private IReadOnlyList<PlanarPartSelection.Item> PreviewCopies(Row row)
      {
        return CopiesAt(row,row.Id,VisiblePlacement(row));
      }
      private IReadOnlyList<PlanarPartSelection.Item> InstancePreviewCopies(Row row,NestPackingEngine.Placement placement)=>
        CopiesAt(row,placement.Id,placement.Id==row.Id?VisiblePlacement(row):InstanceTransform(row,placement));
      private Transform InstanceTransform(Row row,NestPackingEngine.Placement placement)
      {
        var frame=PlanarPartSplitter.RotatedFrame(row.Part.Plane,RhinoMath.ToRadians(MaterialBasisAngle-placement.Pose.Rotation));
        var bounds=Bounds(row,placement.Pose.Rotation); var target=DisplayTablePlane(placement.Table);
        var transform=Transform.Translation(target.XAxis*(placement.X-bounds.Min.X)+target.YAxis*(placement.Y-bounds.Min.Y))*Transform.PlaneToPlane(frame,target);
        return placement.Pose.Flipped?Transform.Mirror(target.PointAt(placement.X+(bounds.Max.X-bounds.Min.X)/2,0),target.XAxis)*transform:transform;
      }
      private IReadOnlyList<PlanarPartSelection.Item> CopiesAt(Row row,int id,Transform transform)
      {
        if(_previewCopies.TryGetValue(id,out var existing)&&existing.Transform==transform&&Nullable.Equals(existing.DrawnGuide,row.DrawnGuide)) return existing.Items;
        if(existing.Items!=null&&Nullable.Equals(existing.DrawnGuide,row.DrawnGuide)&&existing.Transform.TryGetInverse(out var inverse))
        {
          var delta=transform*inverse;
          if(delta.Determinant>0&&existing.Items.All(item=>item.Geometry.Transform(delta)))
          {_previewCopies[id]=(transform,existing.Items,row.DrawnGuide);return existing.Items;}
        }
        if(existing.Items!=null) foreach(var item in existing.Items) item.Geometry.Dispose();
        var copies=new List<PlanarPartSelection.Item>();
        foreach(var item in PartItemsForCopies(row))
        { var copy=TransformedCopy(item.Geometry,transform); copies.Add(item with {Geometry=copy}); }
        _previewCopies[id]=(transform,copies,row.DrawnGuide); return copies;
      }
      private IEnumerable<PlanarPartSelection.Item> PartItemsForCopies(Row row)=>row.Part.Items.Where(item=>
        !row.DrawnGuide.HasValue||item.Geometry is not Curve curve||curve.IsClosed||!IsGrainMarker(_doc,item.Attributes));
      private Transform VisiblePlacement(Row row)
      {
        var placement=VisibleResult.Placements.FirstOrDefault(part=>part.Id==row.Id);
        return InstanceTransform(row,placement??new NestPackingEngine.Placement(row.Id,row.Table,row.X,row.Y,new NestPackingEngine.Pose(0,0,row.Rotation) {Flipped=row.Flipped}));
      }

      private bool CanFineTune=>!_closed&&!_packing&&!_placing&&!_locationPicking&&!PackingBlocked()&&
        _result.Placements.Count>0;
      private Row? PlacementOwner(int id)=>_rows.FirstOrDefault(row=>row.OwnsInstance(id));
      private bool PartIsFixed(Row row,int id)=>id==row.Id?row.Fixed:_manualInstances.ContainsKey(id);
      private NestPackingEngine.Placement[] ManualSelection()
      {var rows=SelectedParts;return _result.Placements.Where(part=>rows.Any(row=>row.OwnsInstance(part.Id))&&
        (_manualSelectedInstances.Count>0?_manualSelectedInstances.Contains(part.Id):_activePreviewInstance==null||rows.Length>1||part.Id==_activePreviewInstance)).ToArray();}
      private void SelectManualPart(NestPackingEngine.Placement hit,bool toggle)
      {
        var ids=ManualSelection().Select(part=>part.Id).ToHashSet();
        if(toggle){if(!ids.Add(hit.Id))ids.Remove(hit.Id);}
        else if(!ids.Contains(hit.Id)||_manualSelectedInstances.Count==0&&SelectedParts.Length==1)ids=[hit.Id];
        SelectManualInstances(ids,hit.Id);
      }
      private void ClearPartFocus()=>SelectManualInstances([]);
      private void SelectManualInstances(HashSet<int> ids,int? focus=null)
      {
        if(_liveTables.Count==0)_activeTable=null;
        _manualSelectedInstances.Clear();_manualSelectedInstances.UnionWith(ids);
        var owners=ids.Select(PlacementOwner).OfType<Row>().ToHashSet();bool previous=_updating;_updating=true;
        try
        {
          _grid.UnselectAll();
          for(int index=0;index<_visibleRows.Count;index++)if(owners.Contains(_visibleRows[index]))_grid.SelectRow(index);
        }
        finally{_updating=previous;}
        _activePreviewInstance=ids.Count==1?ids.Single():null;if(ids.Count==0)_pivotVisible=false;UpdateEditor();RefreshHighlights();_doc.Views.Redraw();
        var owner=focus.HasValue?PlacementOwner(focus.Value):owners.FirstOrDefault();
        if(owner!=null&&owners.Contains(owner))RevealPartRow(owner);else _revealedPart=null;
      }
      private bool SelectManualBox(RhinoView view,System.Drawing.Point start,System.Drawing.Point end,bool add,bool remove)
      {
        if(!CanFineTune)return false;
        var rectangle=NestDocumentPicking.SelectionRectangle(start,end);bool crossing=end.X<start.X;
        view.ActiveViewport.GetFrustumLine(rectangle.Left+rectangle.Width/2,rectangle.Top+rectangle.Height/2,out var ray);
        using var context=new PickContext {View=view,PickLine=ray,PickStyle=crossing?PickStyle.CrossingPick:PickStyle.WindowPick,PickMode=PickMode.Wireframe,PickGroupsEnabled=false};
        context.SetPickTransform(view.ActiveViewport.GetPickTransform(rectangle));context.UpdateClippingPlanes();
        var hits=new HashSet<int>();
        foreach(var part in _result.Placements)
        {
          var row=PlacementOwner(part.Id);if(row==null)continue;
          var outline=PreviewOutline(row,part);
          if(!context.PickFrustumTest(outline.GetBoundingBox(true),out bool contained))continue;
          if(contained){hits.Add(part.Id);continue;}
          if(crossing){using var nurbs=outline.ToNurbsCurve();if(context.PickFrustumTest(nurbs,out _,out _,out _))hits.Add(part.Id);}
        }
        if(hits.Count==0)return false;
        var selected=add||remove?ManualSelection().Select(part=>part.Id).ToHashSet():[];
        if(remove)selected.ExceptWith(hits);else selected.UnionWith(hits);
        SelectManualInstances(selected);return true;
      }
      private bool CompatibleManualFrames(IReadOnlyList<NestPackingEngine.Placement> parts)
      {
        var frame=DisplayTablePlane(parts[0].Table);
        return parts.All(part=>DisplayTablePlane(part.Table).XAxis.EpsilonEquals(frame.XAxis,ConfiguredPoseDimensionTolerance)&&
          DisplayTablePlane(part.Table).YAxis.EpsilonEquals(frame.YAxis,ConfiguredPoseDimensionTolerance));
      }
      private Point3d ManualPivot(IReadOnlyList<NestPackingEngine.Placement> parts)
      {
        var frame=DisplayTablePlane(parts[0].Table);var bounds=BoundingBox.Empty;
        foreach(var part in parts)
        {
          var plane=DisplayTablePlane(part.Table);
          foreach(double x in new[]{part.X,part.X+part.Pose.Width})foreach(double y in new[]{part.Y,part.Y+part.Pose.Length})
          {frame.ClosestParameter(plane.PointAt(x,y),out double u,out double v);bounds.Union(new Point3d(u,v,0));}
        }
        return frame.PointAt(bounds.Center.X,bounds.Center.Y);
      }
      private sealed record ManualTableRule(double Width,double Length,double Gap);
      private NestContourPackingEngine.ManualLayout? _manualScene;
      private NestPackingEngine.Result? _manualSceneLayout;
      private ManualTableRule[] _manualSceneRules=[];
      private double _manualSceneTolerance;
      private NestContourPackingEngine.ManualLayout ManualScene(NestPackingEngine.Result result)
      {
        var rules=ManualRules(result);
        double tolerance=_doc.ModelAbsoluteTolerance;
        if(_manualScene!=null&&_manualSceneTolerance==tolerance&&rules.SequenceEqual(_manualSceneRules)&&_manualScene.Matches(result.Placements))
        {
          if(!ReferenceEquals(result,_manualSceneLayout))_manualScene.Synchronize(result.Placements);
        }
        else
          _manualScene=new(result.Placements,rules.Select((rule,table)=>(rule,table)).ToDictionary(item=>item.table,item=>item.rule.Width),Length,
            result.Placements.ToDictionary(part=>part.Id,part=>rules[part.Table].Gap),
            rules.Select((rule,table)=>(rule,table)).ToDictionary(item=>item.table,item=>item.rule.Length),tolerance);
        _manualSceneRules=rules;_manualSceneTolerance=tolerance;_manualSceneLayout=result;return _manualScene;
      }
      private NestPackingEngine.Pose? ManualPose(Row row,double angle,bool flipped,int? table=null)
      {
        var rules=ManualGrainSettings(row,table??row.Table);
        double evaluated=flipped&&rules.Constrained?NormalizeRotation(-angle-2*EffectiveGuide(rules.Mode,rules.Guide)!.Value):angle;
        if(rules.Constrained&&!PartRotationAllowed(evaluated,rules.Mode,rules.Guide,RotationMode.Any,RotationStep,rules.Reverse,rules.Obey,rules.Deviation))return null;
        return row.ManualGeometry(angle,flipped);
      }
      private NestPackingEngine.Placement? TurnPlacement(NestPackingEngine.Placement before,double angle)
      {
        var row=PlacementOwner(before.Id);if(row==null||ManualPose(row,angle,before.Pose.Flipped,before.Table) is not {} pose)return null;
        var frame=DisplayTablePlane(before.Table);var center=frame.PointAt(before.X+before.Pose.Width/2,before.Y+before.Pose.Length/2);
        if(!InstanceTransform(row,before).TryGetInverse(out var inverse))return null;
        var source=inverse*center;var candidate=before with {X=0,Y=0,Pose=pose};
        frame.ClosestParameter(InstanceTransform(row,candidate)*source,out double x,out double y);
        return candidate with {X=before.X+before.Pose.Width/2-x,Y=before.Y+before.Pose.Length/2-y};
      }
      private NestPackingEngine.Placement[]? TurnManualGroup(IReadOnlyList<NestPackingEngine.Placement> parts,double delta,Point3d pivot)
      {
        var axis=DisplayTablePlane(parts[0].Table).Normal;var rotation=Transform.Rotation(RhinoMath.ToRadians(delta),axis,pivot);
        var result=new List<NestPackingEngine.Placement>();
        foreach(var part in parts)
        {
          var row=PlacementOwner(part.Id);
          // Mirroring reverses the stored angle's handedness, but the group still turns rigidly in world space.
          double angle=part.Pose.Rotation+(part.Pose.Flipped?-delta:delta);
          if(row==null||ManualPose(row,angle,part.Pose.Flipped,part.Table) is not {} pose||!InstanceTransform(row,part).TryGetInverse(out var inverse))return null;
          var frame=DisplayTablePlane(part.Table);var center=frame.PointAt(part.X+part.Pose.Width/2,part.Y+part.Pose.Length/2);
          var candidate=part with {X=0,Y=0,Pose=pose};var shift=rotation*center-InstanceTransform(row,candidate)*(inverse*center);
          result.Add(candidate with {X=shift*frame.XAxis,Y=shift*frame.YAxis});
        }
        return result.ToArray();
      }
      private bool GrainRotation(IReadOnlyList<NestPackingEngine.Placement> parts)=>parts.Any(part=>PlacementOwner(part.Id) is {} row&&ManualGrainSettings(row,part.Table).Constrained);
      private (bool Constrained,GrainMode Mode,double? Guide,bool Reverse,bool Obey,double Deviation) ManualGrainSettings(Row row,int table)
      {
        var material=TableMaterial(table);var mode=row.GrainOverride??material.Grain;var guide=GuideAngle(row);
        bool obey=row.ObeyGrainOverride??material.ObeyGrain;
        return(GrainConstrained(mode,guide,obey),mode,guide,row.AllowReverseOverride??material.AllowReverse,obey,row.GrainDeviationOverride??material.GrainDeviation);
      }
      private bool ManualGrainAllowed(NestPackingEngine.Placement part,double delta)
      {
        if(PlacementOwner(part.Id) is not {} row)return false;
        var rules=ManualGrainSettings(row,part.Table);if(!rules.Constrained)return true;
        double angle=part.Pose.Rotation+(part.Pose.Flipped?-delta:delta);
        if(part.Pose.Flipped)angle=NormalizeRotation(-angle-2*EffectiveGuide(rules.Mode,rules.Guide)!.Value);
        return PartRotationAllowed(angle,rules.Mode,rules.Guide,RotationMode.Any,RotationStep,rules.Reverse,rules.Obey,rules.Deviation);
      }
      private double? ConstrainManualRotation(IReadOnlyList<NestPackingEngine.Placement> parts,double desired)
      {
        var candidates=new List<double>{desired};
        foreach(var part in parts)
        {
          if(PlacementOwner(part.Id) is not {} row)continue;
          var rules=ManualGrainSettings(row,part.Table);if(!rules.Constrained)continue;
          double angle=part.Pose.Rotation+(part.Pose.Flipped?-desired:desired);
          foreach(double allowed in GrainRotationCandidates(angle,rules.Mode,rules.Guide,rules.Reverse,rules.Obey,rules.Deviation,part.Pose.Flipped))
          {double delta=NormalizeRotation(allowed-part.Pose.Rotation)*(part.Pose.Flipped?-1:1);candidates.Add(desired+NormalizeRotation(delta-desired));}
        }
        return candidates.Where(delta=>parts.All(part=>ManualGrainAllowed(part,delta)))
          .OrderBy(delta=>Math.Abs(delta-desired)).Select(delta=>(double?)delta).FirstOrDefault();
      }
      private double RotationStepFor(IReadOnlyList<NestPackingEngine.Placement> parts)=>GrainRotation(parts)?ManualGrainRotationStep:ConfiguredManualKeyboardRotationStep;
      private NestPackingEngine.Placement[]? MirrorManualGroup(IReadOnlyList<NestPackingEngine.Placement> parts,bool horizontal,Point3d pivot)
      {
        var common=DisplayTablePlane(parts[0].Table);var reflection=Transform.Mirror(pivot,horizontal?common.YAxis:common.XAxis);
        var result=new List<NestPackingEngine.Placement>();
        foreach(var part in parts)
        {
          var row=PlacementOwner(part.Id);double angle=NormalizeRotation(part.Pose.Rotation+(horizontal?ManualGrainRotationStep:0));
          if(row==null||ManualPose(row,angle,!part.Pose.Flipped,part.Table) is not {} pose||!InstanceTransform(row,part).TryGetInverse(out var inverse))return null;
          var frame=DisplayTablePlane(part.Table);var center=frame.PointAt(part.X+part.Pose.Width/2,part.Y+part.Pose.Length/2);
          var candidate=part with {X=0,Y=0,Pose=pose};var shift=reflection*center-InstanceTransform(row,candidate)*(inverse*center);
          result.Add(candidate with {X=shift*frame.XAxis,Y=shift*frame.YAxis});
        }
        return result.ToArray();
      }
      private void RotateManual(int direction,bool recover,bool bypass)
      {
        if(!CanFineTune)return;EndManualGesture(true);var selected=ManualSelection();if(selected.Length==0)return;
        if(!CompatibleManualFrames(selected)){_status.Text="Selected tables have incompatible orientations";return;}
        var before=_result;double requested=direction*RotationStepFor(selected);var pivot=ManualPivot(selected);
        double delta=requested;
        if(selected.Any(part=>!ManualGrainAllowed(part,0)))
        {if(ConstrainManualRotation(selected,requested) is not {} recovery){_status.Text="Rotation blocked by grain rules";return;}delta=recovery;}
        var desired=TurnManualGroup(selected,delta,pivot);
        if(desired==null){_status.Text="Rotation blocked by grain rules";return;}
        if(!bypass)
        {
          var scene=ManualScene(before);
          if(recover)
          {
            var relaxed=scene.RelaxRigid(desired);
            if(relaxed==null){_status.Text=scene.RecoveryBudgetExceeded?"Rotation recovery time limit reached; layout unchanged":"No collision-free rotation fits the table";return;}
            desired=relaxed;
          }
          else if(GrainRotation(selected)&&(Math.Abs(delta)>ManualGrainRotationStep/2||selected.Any(part=>!ManualGrainAllowed(part,0))))
          {if(!scene.ValidRigid(desired)){_status.Text="Grain reversal blocked by table edge or part gap";return;}}
          else
          {
            var clock=System.Diagnostics.Stopwatch.StartNew();int steps=Math.Max(1,(int)Math.Ceiling(Math.Abs(delta)/ConfiguredManualRotationCheckStep));
            for(int step=1;step<=steps;step++)
            {
              if(clock.ElapsedMilliseconds>=ConfiguredManualActionMilliseconds){_status.Text="Rotation check time limit reached; layout unchanged";return;}
              var candidate=TurnManualGroup(selected,delta*step/steps,pivot);
              if(candidate==null||!scene.ValidRigid(candidate)){_status.Text="Rotation blocked by table edge or part gap";return;}
            }
          }
        }
        ShowManual(desired);CommitManual(before);_status.Text=$"Rotated {Math.Abs(delta):G} degrees";
      }
      private void AutoRotateSelected()
      {
        if(_closed||_packing||Busy())return;
        EndManualGesture(true);var rows=SelectedParts;if(rows.Length==0)return;
        if(!CanFineTune||ManualSelection() is not {Length:>0} selected)
        {Edit(row=>{row.Fixed=false;row.ManualRotation=false;row.FlipOverride=null;});_status.Text="Automatic rotation enabled; click Nest to apply";return;}
        var before=_result;var scene=ManualScene(before);var changes=new List<NestPackingEngine.Placement>();int blocked=0;
        foreach(var part in selected)
        {
          if(PlacementOwner(part.Id) is not {} row)continue;
          var settings=SettingsForTable(part.Table);var saved=(row.Fixed,row.ManualRotation,row.FlipOverride);
          List<NestPackingEngine.Pose> poses;
          try
          {
            row.Fixed=false;row.ManualRotation=false;row.FlipOverride=null;
            poses=FindMaterialPoses(row,GuideAngle(row),settings.Material.Width,settings.Material.GrainDeviation,
              settings.Material.Grain,settings.Material.ObeyGrain,settings.Material.AllowReverse,settings);
          }
          finally{(row.Fixed,row.ManualRotation,row.FlipOverride)=saved;}
          NestPackingEngine.Placement? chosen=null;
          foreach(var pose in poses.Where(pose=>pose.Flipped==part.Pose.Flipped).OrderBy(pose=>pose.Width*pose.Length)
            .ThenBy(pose=>pose.Length).ThenBy(pose=>Math.Abs(NormalizeRotation(pose.Rotation-part.Pose.Rotation))))
          {
            var candidate=TurnPlacement(part,pose.Rotation);if(candidate==null)continue;
            if(scene.ValidRigid(changes.Append(candidate).ToArray())){chosen=candidate;break;}
          }
          if(chosen!=null)changes.Add(chosen);else blocked++;
        }
        ShowManual(changes);CommitManual(before);
        foreach(var row in rows)
        {row.Fixed=false;row.ManualRotation=false;row.FlipOverride=null;foreach(int id in row.InstanceIds())_manualInstances.Remove(id);SavePartSettings(row);}
        RefreshGrid();RefreshHighlights();_doc.Views.Redraw();
        _status.Text=blocked>0?$"Automatic rotation: {CountText.Format(blocked, "part")} {CountText.Form(blocked, "has", "have")} no collision-free orientation here; re-nest to reposition":
          "Automatic orientation applied; selected parts are free to rotate on the next nest";
      }
      private void RequestPointRotation()
      {
        if(!CanFineTune)return;EndManualGesture(true);var selected=ManualSelection();if(selected.Length==0)return;
        if(!CompatibleManualFrames(selected)){_status.Text="Selected tables have incompatible orientations";return;}
        _rotationPicking=true;_timer.Stop();Enabled=false;
        DeferredNativeCommand.Run(_doc,"_vNestRotateProxy",result=>
        {
          try{RestoreRepeatTarget();EndManualGesture(result==Result.Success);}
          finally
          {
            _rotationPicking=false;
            if(!_closed)
            {
              Enabled=true;UpdateEditor();RefreshHighlights();_doc.Views.Redraw();_timer.Start();
              if(result==Result.Failure)_status.Text="Rotation could not be completed; previous layout retained";
            }
          }
        });
      }
      private Point3d[] RotationSnapPoints()=>RotationSnapPointsExcept(null);
      private Point3d[] RotationSnapPointsExcept(IReadOnlySet<int>? excluded)
      {
        var points=new List<Point3d>();
        foreach(var part in _result.Placements.Where(part=>excluded?.Contains(part.Id)!=true))
        {
          if(PlacementOwner(part.Id) is not {} row)continue;
          foreach(var item in CopiesAt(row,part.Id,InstanceTransform(row,part)))
          {
            if(item.Geometry is Curve curve)
            {
              points.Add(curve.PointAtStart);points.Add(curve.PointAtEnd);points.Add(curve.PointAtNormalizedLength(.5));
              var segments=curve.DuplicateSegments();try{foreach(var segment in segments)points.Add(segment.PointAtStart);}finally{foreach(var segment in segments)segment.Dispose();}
            }
            else if(item.Geometry is AnnotationBase text)points.Add(text.Plane.Origin);
          }
        }
        return points.Where(point=>point.IsValid).Distinct().ToArray();
      }
      private sealed class PointRotationTarget : GetTransform
      {
        private readonly NestWindow _window;
        private long _tick;
        internal PointRotationTarget(NestWindow window,IEnumerable<Guid> ids)
        {
          _window=window;
          using var objects=new Rhino.Collections.TransformObjectList();
          foreach(var id in ids.Distinct())if(window._doc.Objects.FindId(id) is {IsDeleted:false} obj)objects.Add(obj);
          AddTransformObjects(objects);ObjectList.DisplayFeedbackEnabled=false;
        }
        public override Transform CalculateTransform(RhinoViewport viewport,Point3d point)
        {
          if(_window._manualGesture is not {} gesture)return Transform.Identity;
          long now=System.Environment.TickCount64;
          if(now-_tick>=ConfiguredManualPreviewInterval)
          {_tick=now;_window.MoveManualGesture(gesture,point,0,ControlPressed,ShiftPressed);}
          var before=gesture.Before.Placements.First(part=>gesture.Ids.Contains(part.Id));
          var after=_window._result.Placements.First(part=>part.Id==before.Id);
          return _window.PlacementOwner(before.Id) is {} row&&_window.InstanceTransform(row,before).TryGetInverse(out var inverse)?
            _window.InstanceTransform(row,after)*inverse:Transform.Identity;
        }
      }
      internal static (Circle Circle,Line Reference,Line Radius,Arc? Sweep) PointRotationGuides(Plane frame,Point3d pivot,Point3d reference,double angle)
      {
        var radial=frame.ClosestPoint(reference)-pivot;double radius=radial.Length;
        var tangent=Vector3d.CrossProduct(frame.Normal,radial);var plane=new Plane(pivot,radial,tangent);
        var circle=new Circle(plane,radius);double radians=RhinoMath.ToRadians(angle);
        Arc? sweep=Math.Abs(radians)>RhinoMath.ZeroTolerance?new Arc(new Circle(new Plane(pivot,radial,angle<0?-tangent:tangent),radius),Math.Min(Math.Abs(radians),Math.PI*2)):null;
        return(circle,new Line(pivot,circle.PointAt(0)),new Line(pivot,circle.PointAt(radians)),sweep);
      }
      private bool PointRotationOwnsPart(int id)=>_pointRotationDrawing&&_manualGesture?.Ids.Contains(id)==true;
      internal Result PickRequestedRotation()
      {
        if(_listDragRows is {} rows)return PickListDrag(rows);
        if(!_rotationPicking||_closed||ManualSelection() is not {Length:>0} selected)return Result.Cancel;
        var frame=DisplayTablePlane(selected[0].Table);var snaps=RotationSnapPoints();bool committed=false;
        GetPoint Getter(string prompt,GetPoint? provided=null)
        {
          var getter=provided??new GetPoint();getter.DynamicDrawColor=PointRotationGuideColor;getter.SetCommandPrompt(prompt);getter.Constrain(frame,false);
          getter.PermitObjectSnap(ConfiguredLocationObjectSnaps);getter.EnableObjectSnapCursors(ConfiguredLocationObjectSnaps);getter.AddSnapPoints(snaps);return getter;
        }
        try
        {
          RhinoApp.SetFocusToMainWindow(_doc);
          using var pivotGetter=Getter("Rotation pivot");if(pivotGetter.Get()!=GetResult.Point)return Result.Cancel;
          var pivot=pivotGetter.Point();Point3d reference;
          while(true)
          {
            using var referenceGetter=Getter("Rotation reference point");referenceGetter.SetBasePoint(pivot,true);referenceGetter.DrawLineFromPoint(pivot,true);
            if(referenceGetter.Get()!=GetResult.Point)return Result.Cancel;
            reference=referenceGetter.Point();if(reference.DistanceTo(pivot)>_doc.ModelAbsoluteTolerance)break;
          }
          _manualGesture=new(_result,selected.Select(part=>part.Id).ToHashSet(),frame,reference,pivot,Guid.Empty,0,true,false,ManualScene(_result));
          _pointRotationDrawing=true;
          foreach(var id in selected.Where(part=>_liveParts.ContainsKey(part.Id)).SelectMany(part=>_liveParts[part.Id]))
            if(_doc.Objects.FindId(id) is {} obj){_gestureObjectIds.Add(id);_gestureObjectSerials.Add(obj.RuntimeSerialNumber);}
          RefreshHighlights();_doc.Views.Redraw();
          using var target=new PointRotationTarget(this,selected.Where(part=>_liveParts.ContainsKey(part.Id)).SelectMany(part=>_liveParts[part.Id]));
          Getter("Rotation target point; Ctrl bypasses obstacles, Shift recovers around obstacles",target);
          target.ClearSnapPoints();target.AddSnapPoints(RotationSnapPointsExcept(_manualGesture.Ids));
          target.SetBasePoint(pivot,true);
          target.DynamicDraw+=(_,e)=>
          {
            if(_manualGesture is not {} gesture)return;
            _preview.DrawPointRotation(e.Display);
            var first=_result.Placements.First(part=>part.Id==selected[0].Id);
            double angle=NormalizeRotation(first.Pose.Rotation-selected[0].Pose.Rotation)*(first.Pose.Flipped?-1:1);
            var guides=PointRotationGuides(frame,pivot,reference,angle);
            e.Display.DrawCircle(guides.Circle,PointRotationGuideColor,ConfiguredPointRotationGuideWidth);
            e.Display.DrawLine(guides.Reference,PointRotationGuideColor,ConfiguredPointRotationGuideWidth);
            e.Display.DrawLine(guides.Radius,PointRotationGuideColor,ConfiguredPointRotationGuideWidth);
            if(guides.Sweep is {} arc)e.Display.DrawArc(arc,PointRotationGuideColor,ConfiguredPointRotationGuideWidth);
            e.Display.DrawPoint(pivot,PointStyle.X,ConfiguredPointRotationPivotSize,PointRotationGuideColor);
          };
          if(target.GetXform()!=GetResult.Point)return Result.Cancel;
          if(_manualGesture is {} active)MoveManualGesture(active,target.Point(),0,ControlPressed,ShiftPressed);
          committed=true;return Result.Success;
        }
        catch(Exception ex){Log.Write("vNest","point rotation failed: {0}",ex);return Result.Failure;}
        finally{_pointRotationDrawing=false;if(!committed)EndManualGesture(false);RefreshHighlights();_doc.Views.Redraw();}
      }
      private void FlipManual(bool horizontal,bool bypass)
      {
        if(!CanFineTune)return;EndManualGesture(true);var selected=ManualSelection();if(selected.Length==0)return;
        if(!CompatibleManualFrames(selected)){_status.Text="Selected tables have incompatible orientations";return;}
        var before=_result;var desired=MirrorManualGroup(selected,horizontal,ManualPivot(selected));
        if(desired==null){_status.Text="Flip blocked by grain rules";return;}
        if(!bypass&&!ManualScene(before).ValidRigid(desired)){_status.Text="Flip blocked by table edge or part gap; Ctrl bypasses obstacles";return;}
        ShowManual(desired);CommitManual(before);_status.Text=horizontal?"Mirrored horizontally":"Mirrored vertically";
      }
      private void ChangeFlipped(bool flipped)
      {
        if(!CanFineTune){Edit(row=>{row.Flipped=flipped;row.FlipOverride=flipped;});return;}
        EndManualGesture(true);var before=_result;var desired=new List<NestPackingEngine.Placement>();
        foreach(var part in ManualSelection().Where(part=>part.Pose.Flipped!=flipped))
        {
          NestPackingEngine.Placement[] single=[part];
          if(MirrorManualGroup(single,true,ManualPivot(single)) is not {} mirrored)
          {_status.Text="Flip blocked by grain rules";UpdateEditor();return;}
          desired.Add(mirrored[0]);
        }
        if(desired.Count==0){UpdateEditor();return;}
        // Explicit checkbox values, like numeric pose edits, override collisions while retaining grain rules.
        ShowManual(desired);
        if(ReferenceEquals(_result,before)){UpdateEditor();return;}
        CommitManual(before);_status.Text=flipped?"Flipped selected parts":"Restored selected parts' handedness";
      }
      private void ShowManual(IReadOnlyList<NestPackingEngine.Placement> changes)
      {
        var byId=changes.ToDictionary(part=>part.Id);
        bool live=_liveTables.Count>0&&_manualGesture==null,changed=false,transferred=false;
        var placements=new List<NestPackingEngine.Placement>(_result.Placements.Count);
        foreach(var old in _result.Placements)
        {
          if(!byId.TryGetValue(old.Id,out var part)||(live?SamePlacedPose(old,part):old==part))placements.Add(old);
          else{placements.Add(part);changed=true;transferred|=old.Table!=part.Table;}
        }
        if(changes.Count>0&&!changed)return;
        var next=_result with {Placements=placements};
        if(_liveTables.Count>0&&_manualGesture==null&&changes.Count>0&&!ApplyLiveParts(_result,next))return;
        _result=next;
        if(transferred)
        {
          if(changes.FirstOrDefault() is {} active)SelectTableRow(active.Table);
          RefreshTableHighlights();UpdateNestButton();
        }
        if(_manualGesture!=null)
        {
          if(_pointRotationDrawing){RefreshLivePartPreviews();return;} // Native DynamicDraw restores its background and redraws only the moving parts.
          RefreshMovingHighlights();
          // View-only redraws can reuse the old scene; moving geometry must invalidate it.
          _doc.Views.Redraw();return;
        }
        if(changes.Count>0)return; // The caller commits immediately; refresh once after row state and native Undo are finalized.
        _place.Enabled=_liveTables.Count==0&&_packedRevision==_layoutRevision;UpdateEditor();RefreshHighlights();RefreshTableRows();
        _totalYardage.Text=TotalYardageText(_result,YardsPerUnit());
        RefreshMaterialUsage(MaterialUsageTotals(_result,CurrentMaterialValues().Name));_doc.Views.Redraw();
      }
      private void CommitManual(NestPackingEngine.Result before)
      {
        if(ReferenceEquals(before,_result)&&_liveUndoRecord==0)return;
        var snapshot=CaptureManualState(before) with {DocumentRecord=_liveUndoRecord};bool changed=false;
        var changedTables=new HashSet<int>();
        foreach(var part in _result.Placements)
        {
          var old=before.Placements.FirstOrDefault(value=>value.Id==part.Id);
          if(old==null||SamePlacedPose(old,part))continue;
          changed=true;_manualInstances[part.Id]=part;
          changedTables.Add(part.Table);if(old!=null)changedTables.Add(old.Table);
          if(PlacementOwner(part.Id) is {} row&&part.Id==row.Id)
          {row.Fixed=true;row.ManualRotation=true;row.Table=part.Table;row.X=part.X;row.Y=part.Y;row.Rotation=part.Pose.Rotation;row.Flipped=part.Pose.Flipped;SavePartSettings(row);}
        }
        if(changed)RecordManualState(snapshot);
        if(_liveUndoRecord!=0&&!changed)
        {EndLiveRecord();_applyingLive=true;try{ExecuteLiveHistory(false);_doc.ClearRedoRecords();}finally{_applyingLive=false;}}
        else
        {
          bool applying=_applyingLive;_applyingLive=true;
          try{if(changed&&_liveUndoRecord!=0)UpdateLiveUsage(changedTables);}
          finally{_applyingLive=applying;EndLiveRecord();}
        }
        _needsNest=false;
        _status.Text=$"{CountText.Format(_result.Tables, "table")}; {CountText.Format(_result.Placements.Count, "part")}; manually adjusted";
        RefreshGrid();RefreshHighlights();_doc.Views.Redraw();
      }
